// GHSA-6pf3-g4xq-854w Claim6：应用自有命令的 ACL 声明面。
//
// Tauri 2 语义（官方 v2.tauri.app/security/capabilities）：经 `generate_handler!` 注册的
// **应用自有命令默认对所有窗口/WebView 放行**（与插件命令相反）。本仓 `lib.rs` 的
// `generate_handler!` 注册 31 项（含 files/secure_load 等敏感命令），此前 build.rs 是裸
// `tauri_build::build()`、无 `permissions/`，capabilities 只列插件权限 → 悬浮窗（加载同一份前端
// bundle）能无条件 invoke 任意路径读写与凭据读取。
//
// 收紧口径：在此列出全部自有命令名 → tauri-build 生成 `permissions/autogenerated/<cmd>.toml`
// （`allow-<cmd>` / `deny-<cmd>`）并把应用纳入 ACL 判定；此后**任何**自有命令都必须被某个
// capability 引用其权限才可用，未列出的窗（悬浮三件）一律拒。
//
// ⚠️ 本清单必须与 `src/lib.rs` 的 `generate_handler!` 逐项对齐：漏一项 = 该命令在任何窗都不可用
// （运行期报 "Command xxx not allowed by ACL"）；多一项 = 声明了不存在的命令。
// 两侧一致性由 `tests/app_acl.rs::app_manifest_list_matches_generate_handler` 机械锁定
// （include_str! 读两份源码取名字集合比对，同款「DDL 双轨一致性测试」思路）。
const APP_COMMANDS: &[&str] = &[
    // bridge/mod.rs：通路自检
    "bridge_ping",
    // bridge/secure_store.rs：DPAPI 凭证保险箱（高敏）
    "secure_save",
    "secure_load",
    "secure_delete",
    // bridge/window.rs：主窗自绘标题栏 + 撕悬浮三件
    "desktop_window_minimize",
    "desktop_window_toggle_maximize",
    "desktop_window_close",
    "desktop_close_behavior_set",
    "desktop_floating_open",
    "desktop_floating_close",
    // bridge/autostart.rs：开机自启
    "desktop_autostart_set",
    "desktop_autostart_get",
    // bridge/db.rs：本地库路径与 WAL 边车
    "desktop_local_db_path",
    "desktop_delete_db_sidecar",
    // bridge/files.rs：文件读写（高敏）
    "desktop_save_file",
    "desktop_check_files",
    "desktop_file_sizes",
    "desktop_read_file_b64",
    "desktop_read_backup_b64",
    "desktop_delete_cache_file",
    "desktop_shihui_home",
    "desktop_cache_dir",
    "desktop_copy_file",
    // bridge/files.rs · S5B：用户自选目录导出/导入（原生对话框跑壳侧，命令不收目标路径参数）
    "desktop_export_save_b64",
    "desktop_import_read_b64",
    // bridge/monitor.rs：前台窗口标题 / 输入空闲（F8 在画时长）
    "desktop_foreground_title",
    "desktop_input_idle_secs",
    // bridge/modules.rs：模块机制（档②波17）
    "desktop_list_module_dirs",
    "desktop_read_module_manifest",
    "desktop_read_module_entry",
    "desktop_module_storage_path",
    "desktop_install_sample_module",
    // tray.rs：托盘 tooltip
    "desktop_tray_set_tooltip",
];

fn main() {
    tauri_build::try_build(
        tauri_build::Attributes::new()
            .app_manifest(tauri_build::AppManifest::new().commands(APP_COMMANDS)),
    )
    .expect("tauri-build 失败（应用命令 ACL 清单见本文件 APP_COMMANDS）");

    // tauri-build 只把 Windows 资源链到 bin，测试 exe 缺 Common Controls v6 manifest 会
    // 在加载期 STATUS_ENTRYPOINT_NOT_FOUND（tray-icon 依赖 TaskDialogIndirect 等 v6 导出）。
    #[cfg(windows)]
    {
        let out_dir = std::path::PathBuf::from(
            std::env::var("OUT_DIR").expect("OUT_DIR should be set by cargo"),
        );
        let rc = out_dir.join("resource.rc");
        if rc.exists() {
            embed_resource::compile_for_tests(&rc, embed_resource::NONE)
                .manifest_required()
                .expect("embed Windows resource into test binaries");
        }
    }
}
